import {camera,mv,clamp} from './math.js';
import {FieldFitter,fieldValue,targetField,fieldLoss,isoMesh} from './field-math.js';

const num=x=>Math.abs(x)>20?x.toExponential(2):x.toFixed(3);
const control=(id,label,min,max,step,value)=>`<label class="control"><span>${label}<output id="${id}-out">${num(value)}</output></span><input id="${id}" aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
function color(v,error=false){const t=clamp(error?v*2:v,0,1),a=error?[247,250,253]:[245,249,253],b=error?[207,113,56]:[44,145,176];if(v<0&&!error)return [139,111,169,255];return [...a.map((x,i)=>Math.round(x+(b[i]-x)*t)),255];}
export class VolumeLab{
  constructor(){this.fitter=new FieldFitter();this.resetView();}
  resetView(){this.selected=0;this.offset=0;this.level=.35;this.yaw=-35;this.pitch=24;this.running=false;this.element=null;this.message='Move the Gaussian to match the target field, or fit its parameters from sampled 3D values.';}
  reset(){this.unmount();this.fitter.reset(1,'box');this.resetView();}
  unmount(){this.running=false;cancelAnimationFrame(this.animation);this.element=null;}
  q(s){return this.element.querySelector(s);}
  mount(element,next){this.element=element;
    element.innerHTML=`<div class="module-heading"><div><p class="eyebrow">03 / APPROXIMATE A 3D SCALAR FUNCTION</p><h2>Fit a Gaussian to a volume.</h2><p class="description">The input is now (x, y, z). Compare a target field with your Gaussian approximation throughout the volume. Colour and camera images come in the next section.</p></div><aside class="model-note"><strong>Direct function fitting</strong>The fit observes scalar target values at 3D sample points. The view below is an inspection tool; it is not a training camera.</aside></div><div class="lab-layout"><aside class="controls"><div class="panel-heading"><h3>3D Gaussian function</h3><button id="volume-reset" class="text-button">Reset ↺</button></div><label class="control"><span>Target field</span><select id="volume-target"><option value="box">Rounded box · non-Gaussian</option><option value="bump">Ellipsoidal Gaussian bump</option><option value="ring">Ring-shaped field</option></select></label>${control('volume-n','Number of Gaussians N',1,8,1,this.fitter.gs.length)}<label class="control"><span>Edit Gaussian</span><select id="volume-selected"></select></label><div class="control-pair">${control('volume-x','Mean x',-1.5,1.5,.01,-.4)}${control('volume-y','Mean y',-1.5,1.5,.01,.35)}</div>${control('volume-z','Mean z',-1.5,1.5,.01,-.3)}<div class="control-pair">${control('volume-sx','Scale σₓ',.08,1.2,.01,.48)}${control('volume-sy','Scale σᵧ',.08,1.2,.01,.48)}</div>${control('volume-sz','Scale σ_z',.08,1.2,.01,.48)}${control('volume-angle','Rotation about z',-90,90,1,0)}${control('volume-a','Amplitude a',-2,2,.01,.7)}<div class="button-row"><button id="volume-run" class="primary-button">Run field fit ▷</button><button id="volume-step" class="small-button">1 update</button><button id="volume-step50" class="small-button">Fit 50 updates</button><button id="volume-lse" class="small-button">LSE amplitudes only</button></div><p class="control-note">The field fit updates means, scales, rotation, and amplitudes. LSE updates only amplitudes. No photographs, camera poses, colour, or opacity enter this objective.</p></aside><div class="visual"><div class="visual-toolbar"><span>TARGET + APPROXIMATION / SAME ISOVALUE</span><span>Drag or use arrows to inspect</span></div><canvas id="volume-world" width="720" height="380" tabindex="0" aria-label="Target and approximation isosurfaces of a 3D scalar field. Drag or use arrow keys to inspect."></canvas><div class="volume-view-controls">${control('volume-level','Shared isovalue',.05,.9,.05,this.level)}${control('volume-slice','Linked slice offset',-1.4,1.4,.02,this.offset)}</div><div class="legend"><span><i class="amber"></i>Target isosurface</span><span><i></i>Gaussian-sum isosurface</span><span>The slices compare actual scalar values.</span></div><div class="volume-slices">${['XY','XZ','YZ'].map(plane=>`<section><h3 id="slice-${plane}-label">${plane}</h3><div class="slice-triplet">${['target','fit','error'].map(kind=>`<figure><figcaption>${{target:'Target',fit:'Approximation',error:'Error ×2'}[kind]}</figcaption><canvas id="slice-${plane}-${kind}" width="96" height="96" aria-label="${plane} slice ${kind}"></canvas></figure>`).join('')}</div></section>`).join('')}</div><div class="metrics"><div class="metric"><span>Volume RMSE</span><strong id="volume-loss">—</strong><small>15³ scalar samples in [−1.5, 1.5]³</small></div><div class="metric"><span>Gaussian count</span><strong id="volume-count">—</strong><small>One field, N basis functions</small></div><div class="metric"><span>Fitting updates</span><strong id="volume-iterations">0</strong><small>Direct 3D supervision</small></div></div></div></div><p class="story-log" id="volume-status" role="status"></p><div class="formula-row"><div><span>Three-dimensional input</span><code>x = (x,y,z), μ ∈ ℝ³</code></div><div><span>The same Gaussian formula</span><code>φ(x) = exp(−½(x−μ)ᵀΣ⁻¹(x−μ))</code></div><div><span>Direct volume objective</span><code>L = meanₓ (Σᵢ aᵢφᵢ(x) − f(x))²</code></div></div><p class="experiment-note"><b>TRY THIS</b>Fit the rounded box with one Gaussian. Inspect all three slices. Switch to the ring: can a single Gaussian represent its hole? Increase N and fit again.</p><details class="concept-details"><summary>What can an ellipsoid view tell us, and what can it hide?</summary><p>An isosurface shows points with the same scalar value. Both surfaces here use the same chosen isovalue. Matching one contour does not guarantee matching the whole function, so the slices and volume RMSE remain visible. Isosurfaces are sampled approximations. The rotation control exposes rotation about z; three separate scales and three mean coordinates still define a genuinely 3D field.</p></details><div class="bottom-nav"><span>DIRECT 3D FUNCTION APPROXIMATION</span><button id="volume-next" class="text-button">Next: Give these Gaussians colour and opacity →</button></div>`;
    this.q('#volume-reset').onclick=()=>{this.reset();this.mount(element,next);};this.q('#volume-next').onclick=()=>next(structuredClone(this.fitter.gs));
    this.q('#volume-target').onchange=e=>{this.running=false;this.fitter.reset(this.fitter.gs.length,e.target.value);this.message='New target field. Fit its scalar values, then inspect the residual slices.';this.update();};
    this.q('#volume-n').oninput=e=>{this.running=false;this.fitter.reset(Number(e.target.value));this.selected=0;this.message='New Gaussian budget; fit or place the new kernels.';this.update();};this.q('#volume-selected').onchange=e=>{this.selected=Number(e.target.value);this.update();};
    for(const [id,key,index]of [['x','mu',0],['y','mu',1],['z','mu',2],['sx','s',0],['sy','s',1],['sz','s',2],['angle','angle'],['a','a']])this.q('#volume-'+id).oninput=e=>{this.running=false;const g=this.fitter.gs[this.selected];if(index!==undefined)g[key][index]=Number(e.target.value);else g[key]=Number(e.target.value);this.fitter.clearMoments();this.message='Manually edited the 3D function approximation.';this.update();};
    this.q('#volume-level').oninput=e=>{this.level=Number(e.target.value);this.update();};this.q('#volume-slice').oninput=e=>{this.offset=Number(e.target.value);this.update();};
    this.q('#volume-lse').onclick=()=>{this.running=false;const result=this.fitter.fitAmplitudes();this.message=`Solved ${this.fitter.gs.length} amplitudes by LSE, with means and shapes fixed. Basis rank ${result.rank}.`;this.update();};
    this.q('#volume-step').onclick=()=>this.steps(1);this.q('#volume-step50').onclick=()=>this.steps(50);this.q('#volume-run').onclick=()=>{cancelAnimationFrame(this.animation);this.running=!this.running;if(this.running)this.tick();this.update();};
    const canvas=this.q('#volume-world');let drag=null;canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,yaw:this.yaw,pitch:this.pitch};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;this.yaw=drag.yaw+(e.clientX-drag.x)*.4;this.pitch=clamp(drag.pitch+(e.clientY-drag.y)*.3,-60,65);this.drawWorld();};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();this.yaw+=({'ArrowLeft':-4,'ArrowRight':4}[e.key]||0);this.pitch=clamp(this.pitch+({'ArrowUp':-4,'ArrowDown':4}[e.key]||0),-60,65);this.drawWorld();};this.update();
  }
  steps(n){for(let i=0;i<n&&this.fitter.iteration<600;i++)this.fitter.step();if(this.fitter.iteration>=600)this.running=false;this.message='Updated the Gaussian parameters using scalar samples throughout the 3D volume.';this.update();}
  tick(){if(!this.running||!this.element)return;this.steps(2);this.animation=requestAnimationFrame(()=>this.tick());}
  update(){if(!this.element)return;this.selected=Math.min(this.selected,this.fitter.gs.length-1);const g=this.fitter.gs[this.selected];this.q('#volume-selected').innerHTML=this.fitter.gs.map((_,i)=>`<option value="${i}">G${i+1}</option>`).join('');this.q('#volume-selected').value=this.selected;this.q('#volume-target').value=this.fitter.kind;this.q('#volume-n').value=this.fitter.gs.length;this.q('#volume-n-out').textContent=this.fitter.gs.length;
    for(const [id,value]of [['x',g.mu[0]],['y',g.mu[1]],['z',g.mu[2]],['sx',g.s[0]],['sy',g.s[1]],['sz',g.s[2]],['angle',g.angle],['a',g.a],['level',this.level],['slice',this.offset]]){const input=this.q('#volume-'+id);if(id==='a'){input.min=Math.min(-2,value*1.2);input.max=Math.max(2,value*1.2);}input.value=value;this.q('#volume-'+id+'-out').textContent=id==='angle'?value.toFixed(0)+'°':num(value);}
    this.q('#volume-loss').textContent=Math.sqrt(fieldLoss(this.fitter.gs,this.fitter.kind)).toFixed(5);this.q('#volume-count').textContent=this.fitter.gs.length;this.q('#volume-iterations').textContent=this.fitter.iteration;this.q('#volume-status').textContent=this.message;this.q('#volume-run').textContent=this.running?'Pause fitting':'Run field fit ▷';for(const id of ['volume-run','volume-step','volume-step50'])this.q('#'+id).disabled=this.fitter.iteration>=600;
    const key=this.fitter.kind+':'+this.level;if(this.targetKey!==key){this.targetMesh=isoMesh(p=>targetField(p,this.fitter.kind),this.level);this.targetKey=key;}this.fitMesh=isoMesh(p=>fieldValue(p,this.fitter.gs),this.level);this.drawWorld();this.drawSlices();
  }
  drawWorld(){if(!this.element)return;const ctx=this.q('#volume-world').getContext('2d');ctx.fillStyle='#f5faff';ctx.fillRect(0,0,720,380);const view=camera(this.yaw,this.pitch,8),screen=p=>{const q=mv(view.r,p);return [360+q[0]*92,190+q[1]*92,q[2]];};
    ctx.strokeStyle='#d6e5ef';ctx.lineWidth=1;for(let axis=0;axis<3;axis++){const a=[0,0,0],b=[0,0,0];a[axis]=-1.5;b[axis]=1.5;const p=screen(a),q=screen(b);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.stroke();ctx.fillStyle='#647f95';ctx.font='13px monospace';ctx.fillText(['x','y','z'][axis],q[0]+5,q[1]+5);}
    const faces=[...(this.targetMesh||[]).map(t=>({p:t.map(screen),type:'target'})),...(this.fitMesh||[]).map(t=>({p:t.map(screen),type:'fit'}))];faces.sort((a,b)=>b.p.reduce((s,p)=>s+p[2],0)-a.p.reduce((s,p)=>s+p[2],0));
    for(const face of faces){ctx.beginPath();face.p.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=face.type==='target'?'#cc8c3e0b':'#2496bd08';ctx.strokeStyle=face.type==='target'?'#b57b3535':'#268cb85a';ctx.lineWidth=.65;ctx.fill();ctx.stroke();}
    ctx.fillStyle='#5f7c93';ctx.font='12px monospace';ctx.fillText(`Shared scalar isovalue ${this.level.toFixed(2)} · inspection view only`,16,24);
  }
  drawSlices(){for(const plane of ['XY','XZ','YZ']){this.q('#slice-'+plane+'-label').textContent=`${plane} · ${plane==='XY'?'z':plane==='XZ'?'y':'x'} = ${this.offset.toFixed(2)}`;const canvases=['target','fit','error'].map(k=>this.q(`#slice-${plane}-${k}`)),contexts=canvases.map(c=>c.getContext('2d')),images=contexts.map(ctx=>ctx.createImageData(96,96));for(let y=0;y<96;y++)for(let x=0;x<96;x++){const u=-1.5+3*x/95,v=1.5-3*y/95,p=plane==='XY'?[u,v,this.offset]:plane==='XZ'?[u,this.offset,v]:[this.offset,u,v],target=targetField(p,this.fitter.kind),fit=fieldValue(p,this.fitter.gs),values=[target,fit,Math.abs(fit-target)];values.forEach((value,i)=>images[i].data.set(color(value,i===2),4*(y*96+x)));}contexts.forEach((ctx,i)=>ctx.putImageData(images[i],0,0));}}
}
